import { supabaseAdmin } from "@/lib/supabase/client";
import { removeUnusedMemoryMedia } from "@/lib/reels/repository";

export const MEDIA_CLEANUP_WARNING = "Destaque salvo, mas não foi possível liberar o arquivo antigo no Storage. A limpeza desse arquivo precisa ser tentada novamente.";

/** Only videos generated by our uploader, in our own public reels bucket.
 * Never delete arbitrary URLs, other buckets, partner images or remote media.
 */
export function managedVideoPath(url: string, publicBase: string): string | null {
  try {
    const candidate = new URL(url);
    const base = new URL(publicBase);
    if (candidate.origin !== base.origin || !candidate.pathname.startsWith(base.pathname)) return null;
    const path = candidate.pathname.slice(base.pathname.length);
    return /^videos\/\d+_[0-9a-f]{12}\.(mp4|webm|mov)$/.test(path) ? path : null;
  } catch {
    return null;
  }
}

/** Called ONLY after the database mutation succeeds. On cleanup failure, keep
 * the successful mutation and return a visible warning instead of claiming
 * that saving failed. Include inactive reels and banners in the reference check.
 */
export async function cleanupReelVideo(url: string): Promise<string | undefined> {
  if (!url) return;
  if (!supabaseAdmin) {
    removeUnusedMemoryMedia(url);
    return;
  }
  const bucket = supabaseAdmin.storage.from("reels");
  const { data: publicUrl } = bucket.getPublicUrl("");
  const path = managedVideoPath(url, publicUrl.publicUrl);
  if (!path) return;
  try {
    // Filename matching also protects references with query strings, fragments,
    // or alternate public URL hosts. Query the DB directly (list() is capped).
    const filename = path.slice("videos/".length);
    const { data, error } = await supabaseAdmin.from("partner_reels")
      .select("id")
      .or(`video_url.like.*${filename}*,poster_url.like.*${filename}*,partner_logo.like.*${filename}*`)
      .limit(1);
    if (error || !data) return MEDIA_CLEANUP_WARNING;
    if (data.length) return;
    const removed = await bucket.remove([path]);
    if (removed.error) return MEDIA_CLEANUP_WARNING;
  } catch {
    return MEDIA_CLEANUP_WARNING;
  }
}
